package dnsresolver

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

func TestStripHostsBlock(t *testing.T) {
	initial := `127.0.0.1 localhost
::1 ip6-localhost

# ========================================================
# Auto-generated by Ex3-UI DNS Resolver (Geo-unblock)
# Do not edit manually - managed automatically
104.21.65.111 chatgpt.com
104.21.65.111 api.openai.com
# ========================================================

192.168.1.1 router
`
	cleaned := stripHostsBlock(initial)
	if strings.Contains(cleaned, "chatgpt.com") {
		t.Errorf("expected chatgpt.com to be removed, got:\n%s", cleaned)
	}
	if !strings.Contains(cleaned, "127.0.0.1 localhost") {
		t.Errorf("expected localhost to be preserved, got:\n%s", cleaned)
	}
	if !strings.Contains(cleaned, "192.168.1.1 router") {
		t.Errorf("expected router to be preserved, got:\n%s", cleaned)
	}
}

// A stray marker mention, or a block whose footer was lost, must never cost the
// operator the rest of /etc/hosts.
func TestStripHostsBlockLeavesIncompleteBlocksAlone(t *testing.T) {
	stray := "127.0.0.1 localhost\n# Auto-generated by Ex3-UI SmartDNS (Geo-unblock) is documented in the wiki\n192.168.1.1 router\n"
	if got := stripHostsBlock(stray); got != stray {
		t.Fatalf("a stray marker mention changed the file:\n%s", got)
	}

	broken := "127.0.0.1 localhost\n\n# ========================================================\n" +
		"# Auto-generated by Ex3-UI SmartDNS (Geo-unblock)\n" +
		"# Do not edit manually - managed automatically\n" +
		"1.2.3.4 chatgpt.com\n192.168.1.1 router\n"
	if got := stripHostsBlock(broken); got != broken {
		t.Fatalf("an unterminated block truncated the file:\n%s", got)
	}

	clean := "127.0.0.1 localhost\n"
	if got := stripHostsBlock(clean); got != clean {
		t.Fatalf("a file without a block changed:\n%s", got)
	}
}

func TestBuildDnsQuery(t *testing.T) {
	msg := buildDnsQuery("chatgpt.com")
	if len(msg.Questions) != 1 {
		t.Fatalf("expected 1 question, got %d", len(msg.Questions))
	}
	if msg.Questions[0].Name.String() != "chatgpt.com." {
		t.Errorf("expected chatgpt.com., got %s", msg.Questions[0].Name.String())
	}
}

func TestSettingsDefaults(t *testing.T) {
	st := GetSettings()
	if st.DnsServer == "" {
		t.Error("expected non-empty default DNS server")
	}
	if st.IntervalHours <= 0 {
		t.Errorf("expected positive interval, got %d", st.IntervalHours)
	}
	if len(st.Domains) == 0 {
		t.Error("expected default domain list")
	}
}

func TestValidateDomain(t *testing.T) {
	valid := []string{
		"chatgpt.com",
		"sub.domain.example.com",
		"xn--80akhbyknj4f.com",
		"domain-with-hyphens.org",
		"a.b.c",
	}
	for _, d := range valid {
		if err := validateDomain(d); err != nil {
			t.Errorf("valid domain %q rejected: %v", d, err)
		}
	}

	invalid := []string{
		"",
		"   ",
		"evil.com\n127.0.0.1 injected.com",
		"has space.com",
		"-hyphenstart.com",
		"hyphenend-.com",
		strings.Repeat("a", 64) + ".com",
		"invalid$char.com",
		"кириллица-без-punycode.рф",
	}
	for _, d := range invalid {
		if err := validateDomain(d); err == nil {
			t.Errorf("invalid domain %q was accepted", d)
		}
	}
}

func TestUpdateHostsBlockToSkipsUnchangedIPs(t *testing.T) {
	hostsPath := filepath.Join(t.TempDir(), "hosts")
	initialContent := "127.0.0.1 localhost\n"
	if err := os.WriteFile(hostsPath, []byte(initialContent), 0o644); err != nil {
		t.Fatal(err)
	}

	entries := []ResolvedEntry{
		{Domain: "chatgpt.com", IP: "179.236.130.11", Status: "OK"},
		{Domain: "claude.ai", IP: "179.236.130.10", Status: "OK"},
		{Domain: "cdn.claude.ai", IP: "", Status: "FAILED"},
	}

	changed, err := updateHostsBlockTo(hostsPath, entries)
	if err != nil || !changed {
		t.Fatalf("first write: changed=%v err=%v, want true nil", changed, err)
	}

	// Simulate an unrelated entry appended later and verify an identical resolve
	// neither rewrites the file nor disturbs the appended line.
	afterFirst, err := os.ReadFile(hostsPath)
	if err != nil {
		t.Fatal(err)
	}
	withTrailing := string(afterFirst) + "172.66.3.170 api.cloudflareclient.com\n"
	if err := os.WriteFile(hostsPath, []byte(withTrailing), 0o644); err != nil {
		t.Fatal(err)
	}
	oldStamp := time.Date(2025, 1, 2, 3, 4, 5, 0, time.UTC)
	if err := os.Chtimes(hostsPath, oldStamp, oldStamp); err != nil {
		t.Fatal(err)
	}

	changed, err = updateHostsBlockTo(hostsPath, entries)
	if err != nil || changed {
		t.Fatalf("unchanged re-resolve: changed=%v err=%v, want false nil", changed, err)
	}
	info, err := os.Stat(hostsPath)
	if err != nil {
		t.Fatal(err)
	}
	if !info.ModTime().Equal(oldStamp) {
		t.Fatalf("hosts file mtime changed on unchanged IPs: got %v, want %v", info.ModTime(), oldStamp)
	}

	// When any resolved IP changes, the file must be updated.
	updatedEntries := []ResolvedEntry{
		{Domain: "chatgpt.com", IP: "179.236.130.12", Status: "OK"},
		{Domain: "claude.ai", IP: "179.236.130.10", Status: "OK"},
	}
	changed, err = updateHostsBlockTo(hostsPath, updatedEntries)
	if err != nil || !changed {
		t.Fatalf("changed IP resolve: changed=%v err=%v, want true nil", changed, err)
	}
	got, err := os.ReadFile(hostsPath)
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(string(got), "179.236.130.12 chatgpt.com") {
		t.Fatalf("expected updated IP in hosts:\n%s", got)
	}
}
